sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // 1. Enforce only one Active reservation per bed ('1' = Active)
    if (current.getValue('status') == '1' && !current.bed.nil()) {
        var activeRes = new GlideRecord('x_2223823_apollo_0_bed_reservations');
        activeRes.addQuery('bed', current.getValue('bed'));
        activeRes.addQuery('status', '1'); // Active
        activeRes.addQuery('sys_id', '!=', current.getUniqueValue());
        activeRes.setLimit(1);
        activeRes.query();

        if (activeRes.hasNext()) {
            gs.addErrorMessage('Only one Active reservation is allowed per bed. An active reservation already exists for this bed.');
            current.setAbortAction(true);
            return;
        }
    }

    // 2. Auto-populate hospital if blank from bed
    if (current.hospital.nil() && !current.bed.nil()) {
        current.setValue('hospital', current.bed.hospital.toString());
    }

    // 3. Compute Expires At = Reserved At + hospital hold hours
    if (!current.reserved_at.nil() && !current.hospital.nil()) {
        var holdHours = 0;
        var hospGr = current.hospital.getRefRecord();
        if (hospGr.isValidRecord()) {
            if (current.getValue('type') == 'Emergency') {
                holdHours = parseInt(hospGr.getValue('hold_hours_emergency'), 10) || 0;
            } else {
                holdHours = parseInt(hospGr.getValue('hold_hours_planned'), 10) || 0;
            }
        }

        // Fallback default if hold hours not configured on hospital record
        if (holdHours <= 0) {
            holdHours = (current.getValue('type') == 'Emergency') ? 4 : 24;
        }

        var gdt = new GlideDateTime(current.getValue('reserved_at'));
        gdt.addSeconds(holdHours * 3600);
        current.setValue('expires_at', gdt.getValue());
    }

})(current, previous);
